function RGB([int]$r,[int]$g,[int]$b){$r+256*$g+65536*$b}
$ink=RGB 17 17 17;$pink=RGB 255 73 161;$cyan=RGB 55 190 235;$yellow=RGB 255 230 75;$white=RGB 255 255 255;$green=RGB 75 222 159;$muted=RGB 79 89 105
function Text($s,$x,$y,$w,$h,$t,$size=16,$bold=$true,$fill=$ink,$align=2){$o=$s.Shapes.AddTextbox(1,$x,$y,$w,$h);$o.TextFrame.TextRange.Text=$t;$o.TextFrame.TextRange.Font.Name='Microsoft YaHei';$o.TextFrame.TextRange.Font.Size=$size;$o.TextFrame.TextRange.Font.Bold=[int]$bold;$o.TextFrame.TextRange.Font.Color.RGB=$fill;$o.TextFrame.TextRange.ParagraphFormat.Alignment=$align;$o.TextFrame.VerticalAnchor=3;$o.TextFrame.WordWrap=-1;$o}
function Rect($s,$x,$y,$w,$h,$fill,$line=$ink,$weight=2.5){$o=$s.Shapes.AddShape(1,$x,$y,$w,$h);$o.Fill.ForeColor.RGB=$fill;$o.Fill.Solid();$o.Line.ForeColor.RGB=$line;$o.Line.Weight=[single]$weight;$o}
function Circle($s,$x,$y,$d,$fill,$label){$o=$s.Shapes.AddShape(9,$x,$y,$d,$d);$o.Fill.ForeColor.RGB=$fill;$o.Fill.Solid();$o.Line.ForeColor.RGB=$ink;$o.Line.Weight=2.5;Text $s $x ($y+2) $d ($d-4) $label 15 $true $ink 2|Out-Null;$o}
function Arrow($s,$x,$y,$w,$h){$o=$s.Shapes.AddShape(33,$x,$y,$w,$h);$o.Fill.ForeColor.RGB=$ink;$o.Fill.Solid();$o.Line.Visible=0;$o}
function Body($s){foreach($o in $s.Shapes){if($o.HasTextFrame-and$o.TextFrame.HasText-and$o.TextFrame.TextRange.Text.Contains('•')){return $o}}}
function CompactBody($s,$left,$top,$width,$height,$size){$b=Body $s;if($b){$b.Left=$left;$b.Top=$top;$b.Width=$width;$b.Height=$height;$b.TextFrame.TextRange.Font.Size=$size}}
